"function model
    % Given parameters
    W = 280000.0;          % weight, lbf
    S = 2730.0;            % wing area, ft^2
    h = 35000.0;           % altitude, ft
    V = 780.0;             % true airspeed, ft/s
    gamma_deg = 5.0;       % climb angle, deg
    phi_deg = 40.0;        % bank angle, deg

    % Lift coefficients
    CL0 = 0.18;
    CLa = 5.6;             % per rad
    CLde = 0.3;            % per rad

    % Drag coefficients
    CD0 = 0.019;
    k = 0.045;

    % Atmosphere
    rho0 = 0.0023769;      % slug/ft^3
    rho = rho0 * exp(-h/23800);
    q = 0.5 * rho * V^2;

    % Thrust installation
    i_T_deg = 3.0;         % thrust line pitch vs body axis, deg
    z_T = 2.2;             % perpendicular arm from CG, ft

    % Pitch coefficients
    Cm0 = 0.025;
    Cmalpha = -0.34;       % per rad
    Cmdelta_e = -0.9;      % per rad
    cbar = 19.5;           % mean aerodynamic chord, ft

    % Convert given angles to radians
    gamma = gamma_deg * pi/180;
    phi = phi_deg * pi/180;
    i_T = i_T_deg * pi/180;

    % Initial guess for unknowns [alpha (rad), T (lbf), delta_e (rad)]
    alpha = 5.0*pi/180;
    T = 30000.0;
    delta_e = -1.0*pi/180;

    % Newton-Raphson iteration on the three coupled equilibrium equations
    for iter = 1:100
        CL = CL0 + CLa*alpha + CLde*delta_e;
        CD = CD0 + k*CL^2;

        % Residual vector F = [F1; F2; F3]
        F1 = q*S*CL*cos(phi) + T*sin(alpha + i_T) - W*cos(gamma);
        F2 = T*cos(alpha + i_T) - q*S*CD - W*sin(gamma);
        F3 = q*S*cbar*(Cm0 + Cmalpha*alpha + Cmdelta_e*delta_e) + T*sin(i_T)*z_T;
        F = [F1; F2; F3];

        % Jacobian matrix (partial derivatives of F w.r.t. [alpha; T; delta_e])
        J = zeros(3,3);
        J(1,1) = q*S*CLa*cos(phi) + T*cos(alpha + i_T);
        J(1,2) = sin(alpha + i_T);
        J(1,3) = q*S*CLde*cos(phi);

        J(2,1) = -T*sin(alpha + i_T) - q*S*2*k*CL*CLa;
        J(2,2) = cos(alpha + i_T);
        J(2,3) = -q*S*2*k*CL*CLde;

        J(3,1) = q*S*cbar*Cmalpha;
        J(3,2) = sin(i_T)*z_T;
        J(3,3) = q*S*cbar*Cmdelta_e;

        % Newton update
        dx = -J\F;

        alpha = alpha + dx(1);
        T = T + dx(2);
        delta_e = delta_e + dx(3);

        if norm(dx, inf) < 1e-12
            break;
        end
    end

    % Convert to output units
    alpha_deg = alpha * 180/pi;
    delta_e_deg = delta_e * 180/pi;
    n = cos(gamma)/cos(phi);

    % Build result struct and write to result.json
    result.alpha_trim_deg = alpha_deg;
    result.thrust_lbf = T;
    result.delta_e_trim_deg = delta_e_deg;
    result.load_factor = n;

    fid = fopen('result.json', 'w');
    fprintf(fid, '%s', jsonencode(result));
    fclose(fid);
end"
